import{_ as t,o,c as s,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const r="/falconcms/screenshots/seo-settings.webp",n="/falconcms/screenshots/seo-audit.webp",i="/falconcms/screenshots/bulk-seo.webp",d="/falconcms/screenshots/editor-seo-keywords.webp",h="/falconcms/screenshots/editor-seo-links.webp",l="/falconcms/screenshots/seo-redirects.webp",y=JSON.parse('{"title":"SEO","description":"","frontmatter":{},"headers":[],"relativePath":"guide/seo.md","filePath":"guide/seo.md","lastUpdated":1791833165000}'),c={name:"guide/seo.md"};function g(p,e,u,m,f,w){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="seo" tabindex="-1">SEO <a class="header-anchor" href="#seo" aria-label="Permalink to &quot;SEO&quot;">​</a></h1><p>FalconCMS takes care of the technical side of SEO on its own and gives you the tools for the rest. Each page carries a clean title, description, canonical address, structured data and breadcrumbs. Sitemaps, robots.txt and redirects are written for you. In the admin, an audit tells you what to fix and a bulk editor lets you fix it fast.</p><p>Nothing here rewrites the SEO title, description or other SEO data you have entered.</p><h2 id="settings-→-seo" tabindex="-1">Settings → SEO <a class="header-anchor" href="#settings-→-seo" aria-label="Permalink to &quot;Settings → SEO&quot;">​</a></h2><p><img src="'+r+'" alt="Settings → SEO"></p><p><em>Site-wide SEO settings: search engine visibility, permalinks, robots.txt, your organization, AI crawlers, IndexNow, the 404 log, Discover and keyword research.</em></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Hide this site from search engines</strong></td><td>For a demo, a staging copy or an unfinished site. Every page says <code>noindex</code> (a robots meta tag, plus an <code>X-Robots-Tag</code> header on everything else), the sitemap is withdrawn and IndexNow stops. robots.txt keeps allowing crawling on purpose, because Google has to fetch a page to see its noindex. While it is on, the SEO Audit reports it as an error, so it is not forgotten at launch.</td></tr><tr><td><strong>Permalinks</strong></td><td>The first part of category, tag and product-category addresses (<code>/category/…</code>). When you change one, the old addresses redirect to the new ones permanently.</td></tr><tr><td><strong>Robots.txt</strong></td><td>The file served at <code>/robots.txt</code>.</td></tr><tr><td><strong>Your business or organization</strong></td><td>Name, logo, social profiles, phone, email and, for a <strong>local business</strong>, the address and price range. Feeds the <code>Organization</code> or <code>LocalBusiness</code> structured data.</td></tr><tr><td><strong>AI crawlers</strong></td><td>Two separate choices: block <strong>AI training</strong> crawlers (GPTBot, Google-Extended, ClaudeBot, Applebot-Extended, CCBot, meta-externalagent), and block <strong>AI search</strong> crawlers (OAI-SearchBot, Claude-SearchBot, PerplexityBot, meta-webindexer). Both are written into robots.txt. Google and Bing search are never affected. A crawler you name yourself in robots.txt keeps your rule.</td></tr><tr><td><strong>Instant indexing (IndexNow)</strong></td><td>Bing, Yandex, Seznam and others hear about a page the moment it is published, changed or deleted. Off by default. Never sent from a local address (<code>localhost</code>, <code>*.test</code>). Google does not use IndexNow; it reads the sitemap.</td></tr><tr><td><strong>Broken links (404 log)</strong></td><td>Records addresses that visitors hit and that do not exist. On by default. See <a href="#redirects-and-the-404-log">Redirects and the 404 log</a>.</td></tr><tr><td><strong>Google Discover &amp; large previews</strong></td><td>Lets Google show a large image in Discover and search results (<code>max-image-preview:large</code>). On by default. The editor warns when a featured image is narrower than the 1200px Discover needs.</td></tr><tr><td><strong>Keyword research</strong></td><td>Free sources for search demand in the editor. See <a href="#search-demand">Search demand</a>.</td></tr></tbody></table><h2 id="what-every-page-carries" tabindex="-1">What every page carries <a class="header-anchor" href="#what-every-page-carries" aria-label="Permalink to &quot;What every page carries&quot;">​</a></h2><p>You don&#39;t set any of this up:</p><ul><li><p><strong>Title and description</strong> exactly as typed. &quot;Pricing — Free, Pro &amp; Agency&quot; stays as written, without <code>&amp;amp;</code> and without the site name added twice.</p></li><li><p><strong>A canonical address</strong> without sort, filter or tracking parameters (<code>?orderby=</code>, <code>?utm_source=</code>). It keeps <code>?page=2</code>, because Google asks each page of a series to name itself.</p></li><li><p><strong>Breadcrumbs:</strong> one trail (Home › Blog › Category › Post) used by the theme&#39;s title bar, the breadcrumb component and the builder&#39;s Breadcrumb element. The same trail goes into the structured data as a <code>BreadcrumbList</code>, so what Google reads matches what visitors see.</p></li><li><p><strong>Structured data:</strong> one linked JSON-LD graph per page:</p><ul><li>the organization, the site and the page;</li><li>a post&#39;s real author as a <code>Person</code>, with a profile page on the author archive;</li><li>a <code>VideoObject</code> for each YouTube or Vimeo video in the post;</li><li>a <code>Product</code> on product pages.</li></ul><p>Plugins add their own through <code>falcon_structured_data</code>.</p></li><li><p><strong>hreflang</strong> links between the translations of a page on a multilingual site, with <code>x-default</code>.</p></li><li><p><strong><code>noindex</code></strong> on pages nobody should land on from a search:</p><ul><li>the site&#39;s search results;</li><li>an archive with no posts in it;</li><li>the shop&#39;s cart, checkout, account and wishlist.</li></ul><p>The same pages are left out of the sitemap.</p></li></ul><div class="tip custom-block"><p class="custom-block-title">The author box</p><p><strong>Customizer → Single Blog → Show Author Box</strong> prints the author&#39;s name, photo and bio under a post, linked to their author page. It shows only for authors who have a bio.</p></div><h2 id="sitemap" tabindex="-1">Sitemap <a class="header-anchor" href="#sitemap" aria-label="Permalink to &quot;Sitemap&quot;">​</a></h2><p><code>/sitemap.xml</code> lists every published, indexable page at the address the site links to, such as <code>/post/my-post</code> for a post. A page set to noindex is left out, and so is the home page&#39;s second address. Each entry lists the page&#39;s images for Google Images: the featured image first, then the images in the content, up to ten.</p><p>A site with more than 1,000 addresses gets a sitemap index instead, pointing to <code>/sitemap-1.xml</code>, <code>/sitemap-2.xml</code> and so on, with 1,000 addresses each. The address you submit to Search Console stays <code>/sitemap.xml</code>.</p><p>A post opened at its bare slug (<code>/my-post</code>) redirects permanently to its real address (<code>/post/my-post</code>), so search engines see one copy of it, not two.</p><h2 id="seo-audit" tabindex="-1">SEO Audit <a class="header-anchor" href="#seo-audit" aria-label="Permalink to &quot;SEO Audit&quot;">​</a></h2><p><strong>Settings → SEO Audit</strong> checks every published page and post and gives the site a score. Each kind of issue is listed with the pages that have it, most important first. <strong>View</strong> opens the page, <strong>Fix</strong> opens its editor.</p><p><img src="'+n+'" alt="Settings → SEO Audit"></p><p><em>The audit: a score, then every issue with the pages it affects. &quot;Fix&quot; issues open on their own; the rest open with &quot;Show N pages&quot;.</em></p><table tabindex="0"><thead><tr><th>Check</th><th>Severity</th></tr></thead><tbody><tr><td>The whole site is hidden from search engines</td><td>Fix</td></tr><tr><td>Empty pages: published pages with no content, which Google treats as missing (&quot;Soft 404&quot;)</td><td>Fix</td></tr><tr><td>Not in Google&#39;s index: from the <a href="/falconcms/guide/search-console.html">Search Console</a> plugin</td><td>Fix</td></tr><tr><td>Missing meta descriptions</td><td>Important</td></tr><tr><td>Duplicate titles</td><td>Important</td></tr><tr><td>Pages nothing links to: no link from other content or a menu</td><td>Important</td></tr><tr><td>Images without alt text</td><td>Important</td></tr><tr><td>Duplicate meta descriptions, titles likely to be cut off, short posts, posts without a featured image, pages hidden from search (noindex)</td><td>Tip</td></tr></tbody></table><p>The audit only reads. It never changes a page. Pages drawn by templates (the home page, the blog page, the shop&#39;s pages) are not reported as empty. Plugins add their own checks through <code>falcon_seo_audit_checks</code>.</p><p>The <strong>Import Google Keyword Planner data</strong> box at the bottom of this screen feeds <a href="#search-demand">Search demand</a>.</p><h2 id="bulk-seo" tabindex="-1">Bulk SEO <a class="header-anchor" href="#bulk-seo" aria-label="Permalink to &quot;Bulk SEO&quot;">​</a></h2><p><strong>Settings → Bulk SEO</strong> shows the SEO title, meta description, focus keyword and noindex of every page, post and product on one screen. It is the fastest way to fix what the audit finds.</p><p><img src="'+i+'" alt="Settings → Bulk SEO"></p><p><em>Filter to what is missing, type, and save only the rows you changed.</em></p><ul><li><strong>Filter</strong> by type, by title, or to what is missing (title, description or focus keyword).</li><li><strong>Character counts</strong> turn green in the ideal range. The title count includes the &quot; - Site name&quot; that Google shows after it.</li><li><strong>A hint</strong> under the focus keyword says whether the keyword is in the title and the description.</li><li><strong>Only the rows you changed are saved.</strong> A changed row turns yellow, and leaving with unsaved changes asks first.</li><li><strong>An empty field means &quot;use the default&quot;</strong>: the page title, or the excerpt. It is never saved as an empty string.</li></ul><h2 id="in-the-editor" tabindex="-1">In the editor <a class="header-anchor" href="#in-the-editor" aria-label="Permalink to &quot;In the editor&quot;">​</a></h2><p>The <strong>SEO Settings</strong> box under the editor has five tabs: <strong>General</strong> (focus keyword, title, description, search preview, analysis), <strong>Social</strong>, <strong>Keywords</strong>, <strong>Internal Linking</strong> and <strong>Advanced</strong> (canonical, noindex, nofollow).</p><h3 id="keywords" tabindex="-1">Keywords <a class="header-anchor" href="#keywords" aria-label="Permalink to &quot;Keywords&quot;">​</a></h3><p>The Keywords tab suggests what the page could rank for and shows where each phrase is still missing: the title, the headings, the first 100 words, the URL and the description. <strong>Use as focus keyword</strong> fills the General tab&#39;s field.</p><p><img src="'+d+'" alt="The editor&#39;s Keywords tab"></p><p><em>Search demand for &quot;laravel cms&quot;, Google&#39;s own suggestions, and the searches Google already shows this page for (with Search Console).</em></p><ul><li><strong>From the page&#39;s own words:</strong> the phrases the page uses most and the rest of your site uses least. It works in English and Bangla, keeps hyphenated words whole and counts plurals together. Builder placeholder text is ignored. The bar shows how strongly a phrase sets this page apart, not how many people search for it.</li><li><strong>Google already shows this page for:</strong> with the <a href="/falconcms/guide/search-console.html">Search Console</a> plugin, the searches the page appeared for in the last 90 days, with their position. A search at position 4–20 whose words are not in the title is marked <strong>Close to the top</strong>, because that is the easiest win there is.</li></ul><h3 id="search-demand" tabindex="-1">Search demand <a class="header-anchor" href="#search-demand" aria-label="Permalink to &quot;Search demand&quot;">​</a></h3><p>How many people search for a keyword, from free sources only. Set them up under <strong>Settings → SEO → Keyword research</strong>:</p><ul><li><strong>Google Keyword Planner:</strong> free with a Google Ads account (no ad needs to run). Download the keyword ideas as CSV and import the file on the SEO Audit tab. Ranges such as &quot;1K – 10K&quot; are kept. Any keyword tool&#39;s CSV with a &quot;Keyword&quot; column and a volume column works too.</li><li><strong>Bing Webmaster Tools:</strong> paste the free API key (Settings → API access in Bing Webmaster Tools). It is stored encrypted.</li><li><strong>Google&#39;s search suggestions:</strong> what people type into Google around a keyword. This is optional and off by default, because it is not an official API. It is only asked when you press <strong>Check</strong>.</li></ul><p>Answers from outside services are kept for a week, so the same question never costs twice.</p><h3 id="internal-linking" tabindex="-1">Internal Linking <a class="header-anchor" href="#internal-linking" aria-label="Permalink to &quot;Internal Linking&quot;">​</a></h3><p>Pages to link to from this one, and pages that mention this one&#39;s focus keyword without linking to it, each with the reason.</p><p><img src="'+h+'" alt="The editor&#39;s Internal Linking tab"></p><p><em>Both directions, with the reason for each suggestion.</em></p><h2 id="redirects-and-the-404-log" tabindex="-1">Redirects and the 404 log <a class="header-anchor" href="#redirects-and-the-404-log" aria-label="Permalink to &quot;Redirects and the 404 log&quot;">​</a></h2><p><strong>Settings → Redirects</strong> holds your redirects, and below them the addresses visitors asked for that do not exist. Each one shows how often it was hit and where the visitor came from. One click turns a broken address into a redirect.</p><p><img src="'+l+'" alt="Redirects and the 404 log"></p><p><em>Broken addresses visitors actually hit, ready to redirect.</em></p><p>When you change a page&#39;s slug, a redirect from the old address is added for you.</p><h2 id="for-developers" tabindex="-1">For developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For developers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hook</th><th>Use</th></tr></thead><tbody><tr><td><code>falcon_seo_noindex</code> (filter)</td><td>Return <code>true</code> to keep a page out of search, the sitemap and the audit.</td></tr><tr><td><code>falcon_breadcrumbs</code> (filter)</td><td>Change the breadcrumb trail.</td></tr><tr><td><code>falcon_structured_data</code> (filter)</td><td>Add nodes to the page&#39;s JSON-LD graph.</td></tr><tr><td><code>falcon_seo_audit_checks</code> (filter)</td><td>Add a check to the SEO Audit.</td></tr><tr><td><code>falcon_link_suggestions</code>, <code>falcon_keyword_suggestions</code> (filters)</td><td>Add to the editor&#39;s suggestions.</td></tr><tr><td><code>falcon_seo_metabox_after</code> (action)</td><td>Print a panel under the editor&#39;s SEO box.</td></tr></tbody></table><p>See the <a href="/falconcms/api/hooks.html">Hooks API</a> for their arguments.</p>',50)])])}const k=t(c,[["render",g]]);export{y as __pageData,k as default};
